functions.hamt_node_remove:
_Bool hamt_node_remove(hamt_node_t *node, unsigned int hash, int lvl, void *key, equals_fn_t equals_fn,
                       key_value_t *removed_kv)
{
    hamt_node_t *children = get_children_pointer(node);
    int symbol = hamt_get_symbol(hash, lvl);
    unsigned int shifted = (node->sub.bitmap) >> symbol;
    _Bool child_exists = shifted & 1;
    _Bool removed = 0;
    if (child_exists)
    {
        int child_position = __builtin_popcount(shifted >> 1);
        hamt_node_t *subnode = &children[child_position];
        if (is_leaf(subnode))
        {
