             : __assert_fail("children_size == 1", "lib/hamta.c", 257, __extension__ __PRETTY_FUNCTION__));
        hamt_node_t *only_remaining_child = &children[0];
        if (is_leaf(only_remaining_child))
        {
            *node = *only_remaining_child;
            free(children);
        }
    }
    return removed;
}

