    {
        hamt_node_t *children = get_children_pointer(node);
        int children_size = __builtin_popcount(node->sub.bitmap);
        for (int i = 0; i < children_size; i++)
            hamt_node_destroy(&children[i], deallocate_fn);
        free(children);
