    return hamt_node_search(trie->root, hash, 0, key, trie->equals_fn);
}

functions.hamt_remove:
_Bool hamt_remove(hamt_t *trie, void *key, key_value_t *removed_kv)
{
    unsigned int hash = trie->hash_fn(key);
    if (trie->size == 0)
        return 0;
    _Bool removed = 0;
    if (trie->size == 1)
    {
        ((is_leaf(trie->root))
             ? (void)(0)
             : __assert_fail("is_leaf(trie->root)", "lib/hamta.c", 357, __extension__ __PRETTY_FUNCTION__));
        removed_kv->key = trie->root->leaf.key;
        removed_kv->value = trie->root->leaf.value;
        removed = 1;
    }
    else
        removed = hamt_node_remove(trie->root, hash, 0, key, trie->equals_fn, removed_kv);
    if (removed)
        trie->size--;
    return removed;
}

functions.hamt_destroy:
void hamt_destroy(hamt_t *trie, deallocate_fn_t deallocate_fn)
{
    if (trie->size > 0)
        hamt_node_destroy(trie->root, deallocate_fn);
    free(trie->root);
    free(trie);
}

